import type { Tier } from './live-events';

export type SideId = 'A' | 'B';

export const SIDES: readonly SideId[] = ['A', 'B'];

export function otherSide(side: SideId): SideId {
  return side === 'A' ? 'B' : 'A';
}

/** 档位效果。克制环：加速 → 克爆发；护盾 → 克加速；爆发（精英锦鲤/神龙）→ 克护盾。 */
export type TierEffect =
  | { kind: 'fry' }
  | { kind: 'accel'; boost: number; durationMs: number }
  | { kind: 'shield'; durationMs: number }
  | { kind: 'elite'; suppressFry: number; durationMs: number }
  | { kind: 'strengthen'; boost: number; durationMs: number }
  | { kind: 'dragon'; suppress: number; durationMs: number }
  | { kind: 'leap' };

export interface TierRule {
  /** 助力值（贡献分）：用于榜单、归因、成就。与价值成正比。 */
  power: number;
  /** 进度（胜负推进），乘数前基数。T5+ 受上限约束（方案 5.9 ⑧）。 */
  progress: number;
  /** instant = 立即推进；flow = 在 flowMs 内匀速兑现（鱼苗单位）。 */
  delivery: 'instant' | 'flow';
  flowMs: number;
  effect: TierEffect;
  /** 外显描述（≤5 字，过词表）。 */
  label: string;
}

export interface SkinRule {
  id: string;
  label: string;
  /** 概率权重（公示值，合计 100）。 */
  weight: number;
  /** 稀有款触发全屏演出。 */
  rare: boolean;
}

